DOCUMENT();

#############
# Load Macros
#############

loadMacros(
  "PGstandard.pl",
  "PGML.pl",
  "AnswerFormatHelp.pl",
  "contextFiniteSolutionSets.pl",
  "contextForm.pl",
  "ORCCA.pl",
  "PGcourse.pl",
);
COMMENT('Authored in PreTeXt');

#######
# Setup
#######

$x = list_random('a'..'n', 'p'..'z', 'A'..'D', 'F'..'N', 'P'..'T', 'V'..'Z');
Context()->variables->are($x => 'Real');
do {
  $m = list_random(-9..9) + random(0.1,0.9,0.1);
  $n = list_random(-9..9) + random(0.1,0.9,0.1);
} until ($m != $n);
$b = list_random(-9..9) + random(0.1,0.9,0.1);
$sol = $b/($n - $m);
Context()->noreduce('(-x)-y', '(-x)+y');
$left = Formula("$m $x + $b")->reduce;
$right = Formula("$n $x")->reduce;
Context("FiniteSolutionSets")->flags->set(useBizarro => 0);
Context()->flags->remove("NumberCheck");
Context()->variables->are($x => 'Real');
$solset = Formula("{$sol}");

#############################
# Exercise Group Introduction
#############################

BEGIN_PGML
Solve the equation.

END_PGML

######
# Body
######

BEGIN_PGML
[`[$left]=[$right]`]

[_]{$solset}{16}

END_PGML

#############
# End Problem
#############

ENDDOCUMENT();
